module.exports = [
  // ── Module 15, Lesson 3: NumPy, Broadcasting in Practice, and the AI Connection ──
  { phaseId, moduleId: m15, lessonId: l15_3, order: 1, difficulty: 'beginner',
    title: 'Genuinely Timing Broadcasting vs. Explicit Loops',
    titleKn: 'Broadcasting vs. Explicit Loops ಅನ್ನೂ ನಿಜವಾಗಿ ಸಮಯ ಅಳೆಯುವುದೂ',
    problem: "1. Create two NumPy arrays: a (1000, 512) matrix and a (512,) vector. Write a pure-Python nested-loop function that adds the vector to every row of the matrix, and a one-line NumPy broadcasting version that does the same.\n2. Genuinely time both using time.perf_counter(), running each at least 5 times and averaging.\n3. Report the real speedup factor you measured (not an assumed '100x'), and confirm both approaches produce numerically identical results using np.allclose().",
    problemKn: "1. ಎರಡು NumPy arrays ರಚಿಸಿ: ಒಂದು (1000, 512) matrix ಮತ್ತು ಒಂದು (512,) vector. ಪ್ರತಿ ಸಾಲಿಗೆ vector ಸೇರಿಸುವ ಒಂದು pure-Python nested-loop function ಬರೆಯಿರಿ, ಮತ್ತು ಅದೇ ಕೆಲಸ ಮಾಡುವ ಒಂದು ಸಾಲಿನ NumPy broadcasting ಆವೃತ್ತಿ.\n2. time.perf_counter() ಬಳಸಿ ಎರಡನ್ನೂ ನಿಜವಾಗಿ ಸಮಯ ಅಳೆಯಿರಿ, ಪ್ರತಿಯೊಂದನ್ನೂ ಕನಿಷ್ಠ 5 ಬಾರಿ ಚಲಾಯಿಸಿ ಸರಾಸರಿ ತೆಗೆದುಕೊಳ್ಳಿ.\n3. ನೀವು ನಿಜವಾಗಿ ಅಳೆದ speedup factor ವರದಿ ಮಾಡಿ, ಮತ್ತು np.allclose() ಬಳಸಿ ಎರಡೂ ವಿಧಾನಗಳು ಸಂಖ್ಯಾತ್ಮಕವಾಗಿ ಒಂದೇ ಫಲಿತಾಂಶ ನೀಡುತ್ತವೆ ಎಂದು ಖಚಿತಪಡಿಸಿ." },
  { phaseId, moduleId: m15, lessonId: l15_3, order: 2, difficulty: 'intermediate',
    title: 'Implementing Batched Cosine Similarity With Broadcasting',
    titleKn: 'Broadcasting ಜೊತೆ Batched Cosine Similarity ಜಾರಿಗೊಳಿಸುವುದೂ',
    problem: "1. Create a (100, 64) matrix of 'query' embeddings and a (500, 64) matrix of 'document' embeddings (random values are fine).\n2. Using only broadcasting and matrix operations (no explicit Python loops), compute the full (100, 500) cosine similarity matrix between every query and every document.\n3. Verify correctness by picking 3 random (query, document) pairs, computing their cosine similarity manually with a simple loop-based formula, and confirming it matches your broadcasted result to within floating-point tolerance.\n4. Time your broadcasted version against a nested-loop version computing the same (100, 500) matrix, and report the real speedup.",
    problemKn: "1. 'query' embeddings ya ಒಂದು (100, 64) matrix ಮತ್ತು 'document' embeddings ya ಒಂದು (500, 64) matrix ರಚಿಸಿ.\n2. ಕೇವಲ broadcasting ಮತ್ತು matrix operations ಬಳಸಿ (ಯಾವುದೇ explicit Python loops ಇಲ್ಲದೆ), ಪ್ರತಿ query ಮತ್ತು ಪ್ರತಿ document ನಡುವೆ ಪೂರ್ಣ (100, 500) cosine similarity matrix ಲೆಕ್ಕಹಾಕಿ.\n3. 3 ಯಾದೃಚ್ಛಿಕ (query, document) ಜೋಡಿಗಳನ್ನೂ ಆಯ್ಕೆ ಮಾಡಿ, ಒಂದು ಸರಳ loop-based formula ಜೊತೆ ಅವುಗಳ cosine similarity ಕೈಯಾರೆ ಲೆಕ್ಕಹಾಕಿ, ಮತ್ತು ಇದು ನಿಮ್ಮ broadcasted ಫಲಿತಾಂಶಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ ಎಂದು ಖಚಿತಪಡಿಸಿ.\n4. ಅದೇ (100, 500) matrix ಲೆಕ್ಕಹಾಕುವ ಒಂದು nested-loop ಆವೃತ್ತಿ ವಿರುದ್ಧ ನಿಮ್ಮ broadcasted ಆವೃತ್ತಿಯನ್ನೂ ಸಮಯ ಅಳೆಯಿರಿ, ಮತ್ತು ನಿಜ speedup ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m15, lessonId: l15_3, order: 3, difficulty: 'advanced',
    title: 'Debugging a Genuine Broadcasting Shape Mismatch',
    titleKn: 'ಒಂದು ನಿಜ Broadcasting Shape Mismatch ಡೀಬಗ್ ಮಾಡುವುದೂ',
    problem: "1. Create a (32, 10, 64) batch tensor (batch, sequence, features) and attempt to add a (10, 1) bias tensor to it directly. Run this and capture the genuine error NumPy raises.\n2. Explain, using NumPy's actual broadcasting rules (aligning shapes from the right), exactly why this specific combination fails -- trace through the shape-compatibility check dimension by dimension.\n3. Fix it by reshaping the bias tensor to the correct shape so it broadcasts correctly against the batch tensor, and confirm the addition now succeeds and produces the expected (32, 10, 64) output.\n4. Construct a second, different bias shape that WOULD broadcast successfully but produce a semantically wrong result (broadcasts without erroring, but applies the bias to the wrong axis) -- run it and explain why silent broadcasting bugs like this are more dangerous than the shape-mismatch error from step 1.",
    problemKn: "1. ಒಂದು (32, 10, 64) batch tensor ರಚಿಸಿ ಮತ್ತು ಅದಕ್ಕೆ ನೇರವಾಗಿ ಒಂದು (10, 1) bias tensor ಸೇರಿಸಲು ಪ್ರಯತ್ನಿಸಿ. ಇದನ್ನೂ ಚಲಾಯಿಸಿ ಮತ್ತು NumPy ನೀಡುವ ನಿಜ error ಸೆರೆಹಿಡಿಯಿರಿ.\n2. NumPy ya ನಿಜ broadcasting ನಿಯಮಗಳು ಬಳಸಿ, ಈ ನಿರ್ದಿಷ್ಟ ಸಂಯೋಜನೆ ಏಕೆ ವಿಫಲವಾಗುತ್ತದೆ ಎಂದು ನಿಖರವಾಗಿ ವಿವರಿಸಿ.\n3. bias tensor ಅನ್ನೂ ಸರಿಯಾದ shape ಗೆ ಮರುರೂಪಿಸಿ ಇದನ್ನೂ ಸರಿಪಡಿಸಿ, ಮತ್ತು addition ಈಗ ಯಶಸ್ವಿಯಾಗುತ್ತದೆ ಎಂದು ಖಚಿತಪಡಿಸಿ.\n4. ಯಶಸ್ವಿಯಾಗಿ broadcast ಆಗುವ ಆದರೆ ಶಬ್ದಾರ್ಥಪೂರ್ಣವಾಗಿ ತಪ್ಪು ಫಲಿತಾಂಶ ನೀಡುವ ಒಂದು ಎರಡನೇ, ಭಿನ್ನ bias shape ನಿರ್ಮಿಸಿ -- ಇದನ್ನೂ ಚಲಾಯಿಸಿ ಮತ್ತು ಇಂತಹ ಮೌನ broadcasting bugs ಹಂತ 1 ya shape-mismatch error ಗಿಂತ ಏಕೆ ಹೆಚ್ಚು ಅಪಾಯಕಾರಿ ಎಂದು ವಿವರಿಸಿ." },

  // ── Module 16, Lesson 3: Practical Matrix Transformations, AI Applications & Build ──
  { phaseId, moduleId: m16, lessonId: l16_3, order: 1, difficulty: 'beginner',
    title: 'Genuinely Building a 2D Image Rotation Pipeline',
    titleKn: 'ಒಂದು 2D Image Rotation Pipeline ಅನ್ನೂ ನಿಜವಾಗಿ ನಿರ್ಮಿಸುವುದೂ',
    problem: "1. Build a rotation matrix for a genuine angle of your choice (e.g. 37 degrees) and apply it to a small set of 2D points representing the corners of a square.\n2. Verify that the rotated square's side lengths and angles are preserved (compute the actual distances and angles before and after, don't just assume rotation preserves them).\n3. Apply the SAME rotation matrix twice in sequence (compose it with itself) and confirm the result matches applying a single rotation of double the angle -- verify this numerically, not just by citing the theory.",
    problemKn: "1. ನಿಮ್ಮ ಆಯ್ಕೆಯ ಒಂದು ನಿಜ angle ಗೆ (ಉದಾ 37 ಡಿಗ್ರಿ) ಒಂದು rotation matrix ನಿರ್ಮಿಸಿ ಮತ್ತು ಅದನ್ನೂ ಒಂದು ಚೌಕದ ಮೂಲೆಗಳನ್ನೂ ಪ್ರತಿನಿಧಿಸುವ 2D points ಗೆ ಅನ್ವಯಿಸಿ.\n2. rotated ಚೌಕದ ಬದಿಯ ಉದ್ದಗಳು ಮತ್ತು ಕೋನಗಳು ಸಂರಕ್ಷಿಸಲ್ಪಟ್ಟಿವೆ ಎಂದು ಪರಿಶೀಲಿಸಿ (ಮೊದಲು ಮತ್ತು ನಂತರ ನಿಜ ದೂರಗಳು ಮತ್ತು ಕೋನಗಳನ್ನೂ ಲೆಕ್ಕಹಾಕಿ, ಕೇವಲ ಊಹಿಸಬೇಡಿ).\n3. ಅದೇ rotation matrix ಅನ್ನೂ ಸತತವಾಗಿ ಎರಡು ಬಾರಿ ಅನ್ವಯಿಸಿ ಮತ್ತು ಫಲಿತಾಂಶ ಎರಡು ಪಟ್ಟು angle ya ಒಂದೇ rotation ಅನ್ವಯಿಸುವುದಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ ಎಂದು ಸಂಖ್ಯಾತ್ಮಕವಾಗಿ ಖಚಿತಪಡಿಸಿ." },
  { phaseId, moduleId: m16, lessonId: l16_3, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Implementing a Data Augmentation Transform Chain',
    titleKn: 'ಒಂದು Data Augmentation Transform Chain ಅನ್ನೂ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ',
    problem: "1. Implement three separate 2x2 or 3x3 (homogeneous) transformation matrices: a scale, a shear, and a rotation, each with parameters you choose.\n2. Compose them into a single combined transformation matrix via matrix multiplication, and apply it to a small point cloud (e.g. 10 random 2D points).\n3. Verify your composed transform is correct by instead applying the three transforms one at a time, in the same order, to the same points, and confirming both approaches give identical results (within floating-point tolerance).\n4. Change the ORDER of composition (e.g. shear-then-rotate vs. rotate-then-shear) and demonstrate with real numbers that the results differ -- report the actual point coordinates for both orders to prove matrix multiplication is not commutative here.",
    problemKn: "1. ಮೂರು ಪ್ರತ್ಯೇಕ transformation matrices ಜಾರಿಗೊಳಿಸಿ: ಒಂದು scale, ಒಂದು shear, ಮತ್ತು ಒಂದು rotation, ಪ್ರತಿಯೊಂದೂ ನಿಮ್ಮ ಆಯ್ಕೆಯ parameters ಜೊತೆ.\n2. ಅವುಗಳನ್ನೂ matrix multiplication ಮೂಲಕ ಒಂದೇ ಸಂಯೋಜಿತ transformation matrix ಆಗಿ ಸಂಯೋಜಿಸಿ, ಮತ್ತು ಒಂದು ಚಿಕ್ಕ point cloud ಗೆ ಅನ್ವಯಿಸಿ.\n3. ಮೂರು transforms ಅನ್ನೂ ಅದೇ ಕ್ರಮದಲ್ಲಿ ಒಂದೊಂದಾಗಿ ಅನ್ವಯಿಸುವ ಮೂಲಕ ನಿಮ್ಮ ಸಂಯೋಜಿತ transform ಸರಿಯಾಗಿದೆ ಎಂದು ಪರಿಶೀಲಿಸಿ, ಮತ್ತು ಎರಡೂ ವಿಧಾನಗಳು ಒಂದೇ ಫಲಿತಾಂಶ ನೀಡುತ್ತವೆ ಎಂದು ಖಚಿತಪಡಿಸಿ.\n4. ಸಂಯೋಜನೆಯ ಕ್ರಮ ಬದಲಾಯಿಸಿ ಮತ್ತು ನಿಜ ಸಂಖ್ಯೆಗಳೊಂದಿಗೆ ಫಲಿತಾಂಶಗಳು ಭಿನ್ನವಾಗಿವೆ ಎಂದು ತೋರಿಸಿ -- matrix multiplication ಇಲ್ಲಿ commutative ಅಲ್ಲ ಎಂದು ಸಾಬೀತುಪಡಿಸಲು ಎರಡೂ ಕ್ರಮಗಳಿಗೆ ನಿಜ point coordinates ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m16, lessonId: l16_3, order: 3, difficulty: 'advanced',
    title: 'Genuinely Building a Mini Vision-Augmentation Benchmark',
    titleKn: 'ಒಂದು Mini Vision-Augmentation Benchmark ಅನ್ನೂ ನಿಜವಾಗಿ ನಿರ್ಮಿಸುವುದೂ',
    problem: "1. Load a real image (or generate a simple synthetic one, e.g. a grid pattern) as a NumPy array, and implement affine-transform-based augmentations (rotation, scale, shear) using explicit matrix construction and coordinate remapping -- not a library's built-in augmentation function.\n2. Apply your augmentations and visually confirm (by saving/plotting) that the transformed image looks geometrically correct (e.g. straight lines stay straight, right angles under shear look sheared).\n3. Measure how many distinct augmented versions of the image you can generate per second on your machine using your from-scratch implementation, and compare that genuine throughput number against a library function (e.g. scipy.ndimage.affine_transform or a torchvision transform) doing the equivalent operation -- report which is faster and by how much, and explain what the library likely does differently to achieve its speed.",
    problemKn: "1. ಒಂದು ನಿಜ image (ಅಥವಾ ಒಂದು ಸರಳ synthetic ಒಂದನ್ನೂ ಉತ್ಪಾದಿಸಿ) ಒಂದು NumPy array ಆಗಿ ಲೋಡ್ ಮಾಡಿ, ಮತ್ತು explicit matrix ನಿರ್ಮಾಣ ಬಳಸಿ affine-transform-based augmentations (rotation, scale, shear) ಜಾರಿಗೊಳಿಸಿ -- ಒಂದು library ya built-in augmentation function ಅಲ್ಲ.\n2. ನಿಮ್ಮ augmentations ಅನ್ವಯಿಸಿ ಮತ್ತು ದೃಶ್ಯವಾಗಿ ಖಚಿತಪಡಿಸಿ ಪರಿವರ್ತಿತ image ಜ್ಯಾಮಿತೀಯವಾಗಿ ಸರಿಯಾಗಿ ಕಾಣುತ್ತದೆ.\n3. ನಿಮ್ಮ from-scratch implementation ಬಳಸಿ ನಿಮ್ಮ machine ಮೇಲೆ ಪ್ರತಿ ಸೆಕೆಂಡ್ ಎಷ್ಟು ವಿಭಿನ್ನ augmented versions ಉತ್ಪಾದಿಸಬಹುದು ಎಂದು ಅಳೆಯಿರಿ, ಮತ್ತು ಆ ನಿಜ throughput ಸಂಖ್ಯೆಯನ್ನೂ ಒಂದು library function ಜೊತೆ ಹೋಲಿಸಿ -- ಯಾವುದೂ ವೇಗವಾಗಿದೆ ಮತ್ತು ಎಷ್ಟು ಎಂದು ವರದಿ ಮಾಡಿ." },

  // ── Module 17, Lesson 3: Backpropagation, Hessian, Taylor Series & Modern AI ──
  { phaseId, moduleId: m17, lessonId: l17_3, order: 1, difficulty: 'beginner',
    title: 'Genuinely Verifying a Taylor Series Approximation',
    titleKn: 'ಒಂದು Taylor Series Approximation ಅನ್ನೂ ನಿಜವಾಗಿ ಪರಿಶೀಲಿಸುವುದೂ',
    problem: "1. Implement a function that computes the first-, second-, and third-order Taylor approximations of sin(x) around x=0, using the actual derivative values at that point.\n2. Genuinely evaluate all three approximations plus the true sin(x) at x=0.1, x=0.5, x=1.0, and x=2.0, and compute the real absolute error of each approximation order at each point.\n3. Report your error table and explain, based on the actual numbers, at what point the approximation quality visibly degrades as x moves away from 0 -- and why adding the third-order term does or doesn't meaningfully help at each of your test points.",
    problemKn: "1. x=0 ಸುತ್ತ sin(x) ya ಮೊದಲ, ಎರಡನೇ, ಮತ್ತು ಮೂರನೇ-order Taylor approximations ಲೆಕ್ಕಹಾಕುವ ಒಂದು function ಜಾರಿಗೊಳಿಸಿ, ಆ ಬಿಂದುವಿನಲ್ಲಿ ನಿಜ derivative ಮೌಲ್ಯಗಳು ಬಳಸಿ.\n2. x=0.1, x=0.5, x=1.0, ಮತ್ತು x=2.0 ನಲ್ಲಿ ಮೂರೂ approximations ಜೊತೆಗೆ ನಿಜ sin(x) ಅನ್ನೂ ನಿಜವಾಗಿ ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ, ಮತ್ತು ಪ್ರತಿ ಬಿಂದುವಿನಲ್ಲಿ ಪ್ರತಿ approximation order ya ನಿಜ absolute error ಲೆಕ್ಕಹಾಕಿ.\n3. ನಿಮ್ಮ error table ವರದಿ ಮಾಡಿ ಮತ್ತು ನಿಜ ಸಂಖ್ಯೆಗಳ ಆಧಾರದ ಮೇಲೆ, x 0 ಇಂದ ದೂರ ಚಲಿಸಿದಂತೆ approximation quality ಎಲ್ಲಿ ಗಮನಾರ್ಹವಾಗಿ ಕುಸಿಯುತ್ತದೆ ಎಂದು ವಿವರಿಸಿ." },
  { phaseId, moduleId: m17, lessonId: l17_3, order: 2, difficulty: 'intermediate',
    title: "Genuinely Computing the Hessian for a Small Neural Network",
    titleKn: 'ಒಂದು ಚಿಕ್ಕ Neural Network ಗಾಗಿ Hessian ಅನ್ನೂ ನಿಜವಾಗಿ ಲೆಕ್ಕಹಾಕುವುದೂ',
    problem: "1. Define a small scalar-output function f(w1, w2) = a simple two-parameter loss (e.g. a tiny quadratic-plus-nonlinear expression involving w1 and w2). Compute its full 2x2 Hessian matrix by hand (symbolic derivatives) and also numerically via finite differences.\n2. Confirm your hand-derived and finite-difference Hessians agree to within a small numerical tolerance -- report the actual max absolute difference between the two.\n3. Compute the Hessian's eigenvalues at a specific point. Based on the real eigenvalue signs, classify that point as a local minimum, maximum, or saddle point, and verify your classification by evaluating f at several nearby points and checking the function actually behaves as your classification predicts.",
    problemKn: "1. ಒಂದು ಚಿಕ್ಕ scalar-output function f(w1, w2) ವ್ಯಾಖ್ಯಾನಿಸಿ. ಅದರ ಪೂರ್ಣ 2x2 Hessian matrix ಅನ್ನೂ ಕೈಯಾರೆ (symbolic derivatives) ಮತ್ತು ಸಂಖ್ಯಾತ್ಮಕವಾಗಿ finite differences ಮೂಲಕ ಲೆಕ್ಕಹಾಕಿ.\n2. ನಿಮ್ಮ ಕೈಯಾರೆ-ಪಡೆದ ಮತ್ತು finite-difference Hessians ಒಂದು ಚಿಕ್ಕ ಸಂಖ್ಯಾತ್ಮಕ ಸಹನಶೀಲತೆಯೊಳಗೆ ಒಪ್ಪುತ್ತವೆ ಎಂದು ಖಚಿತಪಡಿಸಿ.\n3. ಒಂದು ನಿರ್ದಿಷ್ಟ ಬಿಂದುವಿನಲ್ಲಿ Hessian ya eigenvalues ಲೆಕ್ಕಹಾಕಿ. ನಿಜ eigenvalue ಚಿಹ್ನೆಗಳ ಆಧಾರದ ಮೇಲೆ, ಆ ಬಿಂದುವನ್ನೂ ಒಂದು local minimum, maximum, ಅಥವಾ saddle point ಎಂದು ವರ್ಗೀಕರಿಸಿ, ಮತ್ತು ಹತ್ತಿರದ ಹಲವಾರು ಬಿಂದುಗಳಲ್ಲಿ f ಮೌಲ್ಯಮಾಪನ ಮಾಡುವ ಮೂಲಕ ನಿಮ್ಮ ವರ್ಗೀಕರಣ ಪರಿಶೀಲಿಸಿ." },
  { phaseId, moduleId: m17, lessonId: l17_3, order: 3, difficulty: 'advanced',
    title: 'Genuinely Implementing Backpropagation Through a 2-Layer Network by Hand',
    titleKn: 'ಒಂದು 2-Layer Network ಮೂಲಕ Backpropagation ಅನ್ನೂ ಕೈಯಾರೆ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ',
    problem: "1. Implement a tiny 2-layer network (linear -> ReLU -> linear -> MSE loss) using only raw NumPy, and manually derive and implement the backward pass (compute gradients with respect to every weight matrix and bias vector) using the chain rule, without any autograd library.\n2. Verify your hand-derived gradients against PyTorch's autograd: build the identical network in PyTorch with the same weights, run the same forward pass, call .backward(), and compare every gradient tensor to your NumPy implementation's output using a real numerical tolerance check.\n3. Report the maximum absolute difference you found across all gradient tensors. If any mismatch appears, debug it by checking each layer's local gradient formula individually rather than assuming your overall derivation is right.",
    problemKn: "1. ಕೇವಲ raw NumPy ಬಳಸಿ ಒಂದು ಚಿಕ್ಕ 2-layer network (linear -> ReLU -> linear -> MSE loss) ಜಾರಿಗೊಳಿಸಿ, ಮತ್ತು ಯಾವುದೇ autograd library ಇಲ್ಲದೆ chain rule ಬಳಸಿ backward pass ಅನ್ನೂ ಕೈಯಾರೆ ಪಡೆದು ಜಾರಿಗೊಳಿಸಿ.\n2. ನಿಮ್ಮ ಕೈಯಾರೆ-ಪಡೆದ gradients ಅನ್ನೂ PyTorch ya autograd ವಿರುದ್ಧ ಪರಿಶೀಲಿಸಿ: ಅದೇ weights ಜೊತೆ PyTorch ನಲ್ಲಿ ಒಂದೇ network ನಿರ್ಮಿಸಿ, ಅದೇ forward pass ಚಲಾಯಿಸಿ, .backward() ಕರೆ ಮಾಡಿ, ಮತ್ತು ಪ್ರತಿ gradient tensor ಅನ್ನೂ ನಿಮ್ಮ NumPy implementation ya output ಜೊತೆ ಒಂದು ನಿಜ ಸಂಖ್ಯಾತ್ಮಕ ಸಹನಶೀಲತೆ ಪರಿಶೀಲನೆ ಬಳಸಿ ಹೋಲಿಸಿ.\n3. ಎಲ್ಲಾ gradient tensors ಗಳಾದ್ಯಂತ ನೀವು ಕಂಡುಕೊಂಡ ಗರಿಷ್ಠ absolute difference ವರದಿ ಮಾಡಿ. ಯಾವುದೇ ಹೊಂದಾಣಿಕೆಯಿಲ್ಲದಿರುವಿಕೆ ಕಂಡುಬಂದರೆ, ನಿಮ್ಮ ಒಟ್ಟಾರೆ derivation ಸರಿ ಎಂದು ಊಹಿಸುವ ಬದಲು ಪ್ರತಿ layer ya local gradient formula ಪ್ರತ್ಯೇಕವಾಗಿ ಪರಿಶೀಲಿಸಿ ಡೀಬಗ್ ಮಾಡಿ." },

  // ── Module 18, Lesson 2: Building a Miniature Autograd Engine ──
  { phaseId, moduleId: m18, lessonId: l18_2, order: 1, difficulty: 'beginner',
    title: 'Genuinely Building a Scalar Autograd Value Class',
    titleKn: 'ಒಂದು Scalar Autograd Value Class ಅನ್ನೂ ನಿಜವಾಗಿ ನಿರ್ಮಿಸುವುದೂ',
    problem: "1. Implement a minimal Value class (like micrograd) supporting +, *, and a backward() method that computes gradients via reverse-mode autodiff, tracking a computation graph with parent pointers.\n2. Build a small expression using your Value class, e.g. d = a*b + c, with a=2, b=-3, c=10, and call d.backward().\n3. Manually derive (on paper or in a comment) the expected gradients d(d)/d(a), d(d)/d(b), d(d)/d(c) using calculus, and confirm your engine's computed .grad values for a, b, and c genuinely match your hand-derived values exactly.",
    problemKn: "1. +, *, ಮತ್ತು reverse-mode autodiff ಮೂಲಕ gradients ಲೆಕ್ಕಹಾಕುವ ಒಂದು backward() method ಬೆಂಬಲಿಸುವ ಒಂದು ಕನಿಷ್ಠ Value class (micrograd ನಂತೆ) ಜಾರಿಗೊಳಿಸಿ.\n2. ನಿಮ್ಮ Value class ಬಳಸಿ ಒಂದು ಚಿಕ್ಕ expression ನಿರ್ಮಿಸಿ, ಉದಾ d = a*b + c, ಮತ್ತು d.backward() ಕರೆ ಮಾಡಿ.\n3. calculus ಬಳಸಿ ನಿರೀಕ್ಷಿತ gradients ಅನ್ನೂ ಕೈಯಾರೆ ಪಡೆಯಿರಿ, ಮತ್ತು a, b, ಮತ್ತು c ಗೆ ನಿಮ್ಮ engine ya ಲೆಕ್ಕಹಾಕಿದ .grad ಮೌಲ್ಯಗಳು ನಿಮ್ಮ ಕೈಯಾರೆ-ಪಡೆದ ಮೌಲ್ಯಗಳಿಗೆ ನಿಖರವಾಗಿ ಹೊಂದಿಕೆಯಾಗುತ್ತವೆ ಎಂದು ಖಚಿತಪಡಿಸಿ." },
  { phaseId, moduleId: m18, lessonId: l18_2, order: 2, difficulty: 'intermediate',
    title: 'Extending Your Autograd Engine With tanh and Verifying a Small MLP',
    titleKn: 'tanh ಜೊತೆ ನಿಮ್ಮ Autograd Engine ವಿಸ್ತರಿಸುವುದೂ ಮತ್ತು ಒಂದು ಚಿಕ್ಕ MLP ಪರಿಶೀಲಿಸುವುದೂ',
    problem: "1. Add a tanh() operation to your Value class from the previous exercise, including its correct local-gradient formula (1 - tanh(x)^2) in the backward pass.\n2. Build a tiny single-neuron model using your engine: output = tanh(w*x + b), with genuine numeric values for w, x, b.\n3. Call backward() and record the gradients your engine computes for w and b.\n4. Independently verify these two gradients using numerical finite-difference approximation (perturb w and b by a small epsilon and observe the change in output), and report how closely your engine's analytical gradients match the finite-difference estimates.",
    problemKn: "1. ಹಿಂದಿನ ವ್ಯಾಯಾಮದ ನಿಮ್ಮ Value class ಗೆ ಒಂದು tanh() operation ಸೇರಿಸಿ, backward pass ನಲ್ಲಿ ಅದರ ಸರಿಯಾದ local-gradient formula ಸೇರಿಸಿ.\n2. ನಿಮ್ಮ engine ಬಳಸಿ ಒಂದು ಚಿಕ್ಕ single-neuron model ನಿರ್ಮಿಸಿ: output = tanh(w*x + b), w, x, b ಗೆ ನಿಜ ಸಂಖ್ಯಾತ್ಮಕ ಮೌಲ್ಯಗಳೊಂದಿಗೆ.\n3. backward() ಕರೆ ಮಾಡಿ ಮತ್ತು w ಮತ್ತು b ಗೆ ನಿಮ್ಮ engine ಲೆಕ್ಕಹಾಕುವ gradients ದಾಖಲಿಸಿ.\n4. ಸಂಖ್ಯಾತ್ಮಕ finite-difference approximation ಬಳಸಿ ಈ ಎರಡು gradients ಅನ್ನೂ ಸ್ವತಂತ್ರವಾಗಿ ಪರಿಶೀಲಿಸಿ, ಮತ್ತು ನಿಮ್ಮ engine ya analytical gradients finite-difference ಅಂದಾಜುಗಳಿಗೆ ಎಷ್ಟು ಹತ್ತಿರವಾಗಿ ಹೊಂದಿಕೆಯಾಗುತ್ತವೆ ಎಂದು ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m18, lessonId: l18_2, order: 3, difficulty: 'advanced',
    title: 'Genuinely Handling Variable Reuse in Your Autograd Graph',
    titleKn: 'ನಿಮ್ಮ Autograd Graph ನಲ್ಲಿ Variable Reuse ಅನ್ನೂ ನಿಜವಾಗಿ ನಿಭಾಯಿಸುವುದೂ',
    problem: "A common autograd bug is failing to accumulate (rather than overwrite) gradients when a single Value is used more than once in an expression.\n1. Using your Value class, build the expression y = x*x + x (where x is used twice), with a genuine numeric value for x, and call backward().\n2. Manually derive dy/dx = 2x + 1 and compute its true value at your chosen x.\n3. Check whether your engine's computed x.grad matches this true value. If your backward() implementation OVERWRITES gradients instead of accumulating (+=) them across multiple uses of the same Value, you should see a wrong result -- reproduce this bug deliberately if your engine has it, then fix the backward() method to accumulate gradients correctly, and confirm x.grad now matches the correct 2x+1 value.",
    problemKn: "ಒಂದು ಸಾಮಾನ್ಯ autograd bug ಎಂದರೆ ಒಂದು single Value ಒಂದು expression ನಲ್ಲಿ ಒಂದಕ್ಕಿಂತ ಹೆಚ್ಚು ಬಾರಿ ಬಳಸಿದಾಗ gradients ಅನ್ನೂ ಸಂಗ್ರಹಿಸಲು (overwrite ಮಾಡುವ ಬದಲು) ವಿಫಲವಾಗುವುದೂ.\n1. ನಿಮ್ಮ Value class ಬಳಸಿ, y = x*x + x (x ಎರಡು ಬಾರಿ ಬಳಸಿದ) expression ನಿರ್ಮಿಸಿ, ಒಂದು ನಿಜ ಸಂಖ್ಯಾತ್ಮಕ x ಮೌಲ್ಯ ಜೊತೆ, ಮತ್ತು backward() ಕರೆ ಮಾಡಿ.\n2. dy/dx = 2x + 1 ಕೈಯಾರೆ ಪಡೆದು ನಿಮ್ಮ ಆಯ್ಕೆಯ x ನಲ್ಲಿ ಅದರ ನಿಜ ಮೌಲ್ಯ ಲೆಕ್ಕಹಾಕಿ.\n3. ನಿಮ್ಮ engine ya ಲೆಕ್ಕಹಾಕಿದ x.grad ಈ ನಿಜ ಮೌಲ್ಯಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ. ನಿಮ್ಮ backward() implementation gradients ಅನ್ನೂ ಸಂಗ್ರಹಿಸುವ ಬದಲು ಬರೆಯುತ್ತಿದ್ದರೆ, ಇದನ್ನೂ ಸರಿಪಡಿಸಿ ಮತ್ತು x.grad ಈಗ ಸರಿಯಾದ 2x+1 ಮೌಲ್ಯಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ ಎಂದು ಖಚಿತಪಡಿಸಿ." },

  // ── Module 18, Lesson 3: Gradient Checking & Connecting to PyTorch ──
  { phaseId, moduleId: m18, lessonId: l18_3, order: 1, difficulty: 'beginner',
    title: 'Genuinely Implementing Numerical Gradient Checking',
    titleKn: 'Numerical Gradient Checking ಅನ್ನೂ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ',
    problem: "1. Write a generic gradient_check(f, x, analytical_grad, epsilon=1e-5) function that computes the central-difference numerical gradient (f(x+eps) - f(x-eps)) / (2*eps) for a scalar function f at point x.\n2. Test it on f(x) = x**3 at x=2.0, comparing the numerical gradient to the true analytical derivative (3*x**2).\n3. Genuinely sweep epsilon across several values (1e-2, 1e-4, 1e-6, 1e-8, 1e-10) and report how the numerical-vs-analytical error changes at each -- confirm you can observe the real trade-off where epsilon too large causes truncation error and epsilon too small causes floating-point precision error, using your own measured numbers rather than describing the effect abstractly.",
    problemKn: "1. ಒಂದು ಬಿಂದು x ನಲ್ಲಿ ಒಂದು scalar function f ಗೆ central-difference numerical gradient ಲೆಕ್ಕಹಾಕುವ ಒಂದು generic gradient_check(f, x, analytical_grad, epsilon=1e-5) function ಬರೆಯಿರಿ.\n2. x=2.0 ನಲ್ಲಿ f(x) = x**3 ಮೇಲೆ ಪರೀಕ್ಷಿಸಿ, numerical gradient ಅನ್ನೂ ನಿಜ analytical derivative ಜೊತೆ ಹೋಲಿಸಿ.\n3. epsilon ಅನ್ನೂ ಹಲವಾರು ಮೌಲ್ಯಗಳಾದ್ಯಂತ ನಿಜವಾಗಿ ಸ್ವೀಪ್ ಮಾಡಿ ಮತ್ತು ಪ್ರತಿಯೊಂದರಲ್ಲಿ numerical-vs-analytical error ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ಎಂದು ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m18, lessonId: l18_3, order: 2, difficulty: 'intermediate',
    title: 'Gradient-Checking Your Own Autograd Engine Against Finite Differences',
    titleKn: 'ನಿಮ್ಮ ಸ್ವಂತ Autograd Engine ಅನ್ನೂ Finite Differences ವಿರುದ್ಧ Gradient-Checking ಮಾಡುವುದೂ',
    problem: "1. Take your Value-class autograd engine from Module 18 Part 2 and build a slightly larger expression involving at least 4 operations (mix of +, *, tanh) and 3 distinct input variables.\n2. Call backward() and record all 3 analytical gradients your engine computes.\n3. Genuinely implement and run central-difference gradient checking for each of the 3 variables independently (perturbing one at a time while holding the others fixed), and report the real relative error between your engine's analytical gradients and the finite-difference estimates for each variable -- if any variable's error is surprisingly large, investigate whether it's a genuine bug in your engine or just expected finite-difference imprecision.",
    problemKn: "1. Module 18 Part 2 ya ನಿಮ್ಮ Value-class autograd engine ತೆಗೆದುಕೊಂಡು ಕನಿಷ್ಠ 4 operations ಮತ್ತು 3 ವಿಭಿನ್ನ input variables ಒಳಗೊಂಡ ಸ್ವಲ್ಪ ದೊಡ್ಡ expression ನಿರ್ಮಿಸಿ.\n2. backward() ಕರೆ ಮಾಡಿ ಮತ್ತು ನಿಮ್ಮ engine ಲೆಕ್ಕಹಾಕುವ ಎಲ್ಲಾ 3 analytical gradients ದಾಖಲಿಸಿ.\n3. 3 variables ಪ್ರತಿಯೊಂದಕ್ಕೂ ಸ್ವತಂತ್ರವಾಗಿ central-difference gradient checking ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸಿ ಮತ್ತು ಚಲಾಯಿಸಿ, ಮತ್ತು ಪ್ರತಿ variable ಗೆ ನಿಮ್ಮ engine ya analytical gradients ಮತ್ತು finite-difference ಅಂದಾಜುಗಳ ನಡುವಿನ ನಿಜ relative error ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m18, lessonId: l18_3, order: 3, difficulty: 'advanced',
    title: "Comparing Your Autograd Engine's Gradients to PyTorch's",
    titleKn: 'ನಿಮ್ಮ Autograd Engine ya Gradients ಅನ್ನೂ PyTorch ya ಜೊತೆ ಹೋಲಿಸುವುದೂ',
    problem: "1. Build an identical small computation (same expression, same numeric input values) in both your own Value-class autograd engine AND real PyTorch (using torch.tensor(..., requires_grad=True)).\n2. Run backward()/.backward() in both, and genuinely compare every corresponding gradient value between your engine and PyTorch's autograd, reporting the real max absolute difference.\n3. Now genuinely break something: introduce a deliberate bug in your engine's backward pass for one operation (e.g. forget to multiply by the local derivative for tanh, using only the upstream gradient), re-run the comparison, and confirm your gradient-checking process from the previous exercises would have caught this specific bug -- report the actual discrepancy this bug produces versus PyTorch's correct gradients.",
    problemKn: "1. ನಿಮ್ಮ ಸ್ವಂತ Value-class autograd engine ಮತ್ತು ನಿಜ PyTorch ಎರಡರಲ್ಲೂ ಒಂದೇ ಚಿಕ್ಕ computation ನಿರ್ಮಿಸಿ.\n2. ಎರಡರಲ್ಲೂ backward()/.backward() ಚಲಾಯಿಸಿ, ಮತ್ತು ನಿಮ್ಮ engine ಮತ್ತು PyTorch ya autograd ನಡುವೆ ಪ್ರತಿ ಅನುಗುಣವಾದ gradient ಮೌಲ್ಯ ನಿಜವಾಗಿ ಹೋಲಿಸಿ, ನಿಜ ಗರಿಷ್ಠ absolute difference ವರದಿ ಮಾಡಿ.\n3. ಈಗ ನಿಜವಾಗಿ ಏನನ್ನೂ ಒಡೆಯಿರಿ: ಒಂದು operation ಗೆ ನಿಮ್ಮ engine ya backward pass ನಲ್ಲಿ ಒಂದು ಉದ್ದೇಶಪೂರ್ವಕ bug ಪರಿಚಯಿಸಿ, ಹೋಲಿಕೆ ಮರುಚಲಾಯಿಸಿ, ಮತ್ತು ಹಿಂದಿನ ವ್ಯಾಯಾಮಗಳ ನಿಮ್ಮ gradient-checking ಪ್ರಕ್ರಿಯೆ ಈ ನಿರ್ದಿಷ್ಟ bug ಹಿಡಿಯುತ್ತಿತ್ತು ಎಂದು ಖಚಿತಪಡಿಸಿ." },

  // ── Module 19, Lesson 2: Distributions, Gaussian Behavior & Sampling ──
  { phaseId, moduleId: m19, lessonId: l19_2, order: 1, difficulty: 'beginner',
    title: 'Genuinely Verifying the Central Limit Theorem by Simulation',
    titleKn: 'Simulation ಮೂಲಕ Central Limit Theorem ಅನ್ನೂ ನಿಜವಾಗಿ ಪರಿಶೀಲಿಸುವುದೂ',
    problem: "1. Sample 10,000 values from a genuinely non-Gaussian distribution (e.g. a uniform distribution or an exponential distribution).\n2. Repeatedly draw batches of 30 samples from this distribution and compute each batch's mean, doing this 5,000 times to build a distribution of sample means.\n3. Plot a histogram of your original samples and a histogram of your 5,000 sample means side by side, and genuinely test the sample-means histogram for approximate normality (e.g. using scipy.stats.shapiro or by comparing its skewness/kurtosis to 0/3). Report whether your empirical results confirm the Central Limit Theorem for your specific non-Gaussian source distribution.",
    problemKn: "1. ಒಂದು ನಿಜ non-Gaussian distribution ಇಂದ (ಉದಾ uniform ಅಥವಾ exponential) 10,000 ಮೌಲ್ಯಗಳನ್ನೂ sample ಮಾಡಿ.\n2. ಈ distribution ಇಂದ ಪದೇ ಪದೇ 30 samples ya batches ಸೆಳೆಯಿರಿ ಮತ್ತು ಪ್ರತಿ batch ya mean ಲೆಕ್ಕಹಾಕಿ, ಇದನ್ನೂ 5,000 ಬಾರಿ ಮಾಡಿ sample means ya ಒಂದು distribution ನಿರ್ಮಿಸಿ.\n3. ನಿಮ್ಮ ಮೂಲ samples ya ಒಂದು histogram ಮತ್ತು ನಿಮ್ಮ 5,000 sample means ya ಒಂದು histogram ಪಕ್ಕಪಕ್ಕ ಪ್ಲಾಟ್ ಮಾಡಿ, ಮತ್ತು sample-means histogram ಅನ್ನೂ ಅಂದಾಜು normality ಗಾಗಿ ನಿಜವಾಗಿ ಪರೀಕ್ಷಿಸಿ." },
  { phaseId, moduleId: m19, lessonId: l19_2, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Implementing and Verifying Inverse Transform Sampling',
    titleKn: 'Inverse Transform Sampling ಅನ್ನೂ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ ಮತ್ತು ಪರಿಶೀಲಿಸುವುದೂ',
    problem: "1. Derive the inverse CDF for the exponential distribution with rate lambda=2, and implement a sampler that generates exponential samples using ONLY numpy's uniform random generator plus your derived inverse CDF formula (no np.random.exponential).\n2. Generate 20,000 samples using your sampler.\n3. Compare your samples' empirical mean and variance to the theoretical mean (1/lambda) and variance (1/lambda^2) of the exponential distribution, and genuinely test goodness-of-fit (e.g. via scipy.stats.kstest against the true exponential distribution). Report the real test statistic and p-value, and state whether your implementation passed.",
    problemKn: "1. rate lambda=2 ಜೊತೆ exponential distribution ya inverse CDF ಪಡೆಯಿರಿ, ಮತ್ತು ಕೇವಲ numpy ya uniform random generator ಮತ್ತು ನಿಮ್ಮ ಪಡೆದ inverse CDF formula ಬಳಸಿ exponential samples ಉತ್ಪಾದಿಸುವ ಒಂದು sampler ಜಾರಿಗೊಳಿಸಿ.\n2. ನಿಮ್ಮ sampler ಬಳಸಿ 20,000 samples ಉತ್ಪಾದಿಸಿ.\n3. ನಿಮ್ಮ samples ya empirical mean ಮತ್ತು variance ಅನ್ನೂ theoretical mean ಮತ್ತು variance ಜೊತೆ ಹೋಲಿಸಿ, ಮತ್ತು goodness-of-fit ಅನ್ನೂ ನಿಜವಾಗಿ ಪರೀಕ್ಷಿಸಿ. ನಿಜ test statistic ಮತ್ತು p-value ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m19, lessonId: l19_2, order: 3, difficulty: 'advanced',
    title: 'Genuinely Measuring How Distribution Choice Affects Weight Initialization',
    titleKn: 'Distribution Choice ತೂಕದ Initialization ಮೇಲೆ ಹೇಗೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ ಎಂದು ನಿಜವಾಗಿ ಅಳೆಯುವುದೂ',
    problem: "1. Initialize the weights of a 5-layer linear (no activation) network's weight matrices using 3 different genuine strategies: (a) standard Gaussian N(0,1), (b) Xavier/Glorot initialization, (c) a Gaussian with a variance you pick that's deliberately too large (e.g. N(0, 25)).\n2. Feed the same random input vector through each of the 3 networks and genuinely measure the standard deviation of the activations at each of the 5 layers.\n3. Report your real measured numbers as a table (layer vs. std-dev for each initialization strategy), and explain, based on what you actually observed (not textbook description), which initialization causes activations to explode, which causes them to vanish, and which keeps them stable across layers.",
    problemKn: "1. ಒಂದು 5-layer linear (activation ಇಲ್ಲದ) network ya weight matrices ಅನ್ನೂ 3 ವಿಭಿನ್ನ ನಿಜ ತಂತ್ರಗಳನ್ನೂ ಬಳಸಿ ಪ್ರಾರಂಭಿಸಿ: (a) ಸ್ಟ್ಯಾಂಡರ್ಡ್ Gaussian N(0,1), (b) Xavier/Glorot initialization, (c) ನೀವು ಆಯ್ಕೆ ಮಾಡುವ ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ಬಹಳ ದೊಡ್ಡದಾದ variance ಇರುವ ಒಂದು Gaussian.\n2. ಅದೇ ಯಾದೃಚ್ಛಿಕ input vector ಅನ್ನೂ 3 networks ಪ್ರತಿಯೊಂದರ ಮೂಲಕ ಫೀಡ್ ಮಾಡಿ ಮತ್ತು 5 layers ಪ್ರತಿಯೊಂದರಲ್ಲೂ activations ya standard deviation ನಿಜವಾಗಿ ಅಳೆಯಿರಿ.\n3. ನಿಮ್ಮ ನಿಜ ಅಳೆದ ಸಂಖ್ಯೆಗಳನ್ನೂ ಒಂದು table ಆಗಿ ವರದಿ ಮಾಡಿ, ಮತ್ತು ನೀವು ನಿಜವಾಗಿ ಗಮನಿಸಿದ ಆಧಾರದ ಮೇಲೆ ಯಾವ initialization activations ಸ್ಫೋಟಿಸುವಂತೆ ಮಾಡುತ್ತದೆ, ಯಾವುದೂ ಅವುಗಳನ್ನೂ ಕಣ್ಮರೆಯಾಗಿಸುತ್ತದೆ ಎಂದು ವಿವರಿಸಿ." },

  // ── Module 19, Lesson 3: Log Probabilities, Softmax & Cross-Entropy ──
  { phaseId, moduleId: m19, lessonId: l19_3, order: 1, difficulty: 'beginner',
    title: 'Genuinely Reproducing Softmax Numerical Overflow',
    titleKn: 'Softmax Numerical Overflow ಅನ್ನೂ ನಿಜವಾಗಿ ಮರುಉತ್ಪಾದಿಸುವುದೂ',
    problem: "1. Implement a naive softmax function: exp(x) / sum(exp(x)), with no numerical-stability tricks.\n2. Feed it a logits vector containing a large value, e.g. [1000, 1001, 1002], and genuinely run it. Confirm you get real NaN or inf values, and print the exact intermediate values (the exponentials) that caused the overflow.\n3. Implement the numerically-stable version (subtracting the max logit before exponentiating) and confirm it produces the correct, finite probability distribution on the same input. Verify both versions produce identical results on a 'safe' input like [1, 2, 3] to confirm your stable version is mathematically equivalent, not just avoiding the crash by changing the answer.",
    problemKn: "1. ಒಂದು naive softmax function ಜಾರಿಗೊಳಿಸಿ: exp(x) / sum(exp(x)), ಯಾವುದೇ numerical-stability ತಂತ್ರಗಳಿಲ್ಲದೆ.\n2. ಒಂದು ದೊಡ್ಡ ಮೌಲ್ಯ ಒಳಗೊಂಡ logits vector ಫೀಡ್ ಮಾಡಿ, ಉದಾ [1000, 1001, 1002], ಮತ್ತು ಇದನ್ನೂ ನಿಜವಾಗಿ ಚಲಾಯಿಸಿ. ನಿಜ NaN ಅಥವಾ inf ಮೌಲ್ಯಗಳು ಸಿಗುತ್ತವೆ ಎಂದು ಖಚಿತಪಡಿಸಿ.\n3. ಸಂಖ್ಯಾತ್ಮಕವಾಗಿ-ಸ್ಥಿರ ಆವೃತ್ತಿ ಜಾರಿಗೊಳಿಸಿ (exponentiate ಮಾಡುವ ಮೊದಲು ಗರಿಷ್ಠ logit ಕಳೆಯುವುದೂ) ಮತ್ತು ಇದು ಅದೇ input ಮೇಲೆ ಸರಿಯಾದ, ಸೀಮಿತ probability distribution ಉತ್ಪಾದಿಸುತ್ತದೆ ಎಂದು ಖಚಿತಪಡಿಸಿ." },
  { phaseId, moduleId: m19, lessonId: l19_3, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Implementing Log-Sum-Exp and Cross-Entropy From Scratch',
    titleKn: 'Log-Sum-Exp ಮತ್ತು Cross-Entropy ಅನ್ನೂ ಮೊದಲಿನಿಂದ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ',
    problem: "1. Implement the log-sum-exp trick from scratch: logsumexp(x) = max(x) + log(sum(exp(x - max(x)))).\n2. Using your logsumexp function, implement a numerically-stable log-softmax and then a cross-entropy loss function computed directly from raw logits (not from already-normalized probabilities).\n3. Genuinely compare your from-scratch cross-entropy loss against PyTorch's torch.nn.functional.cross_entropy on the same logits and target label, for at least 3 different logit vectors including one with large-magnitude values that would overflow a naive implementation. Report the real numerical agreement (or disagreement) you found.",
    problemKn: "1. log-sum-exp ತಂತ್ರವನ್ನೂ ಮೊದಲಿನಿಂದ ಜಾರಿಗೊಳಿಸಿ: logsumexp(x) = max(x) + log(sum(exp(x - max(x)))).\n2. ನಿಮ್ಮ logsumexp function ಬಳಸಿ, ಒಂದು ಸಂಖ್ಯಾತ್ಮಕವಾಗಿ-ಸ್ಥಿರ log-softmax ಮತ್ತು ನಂತರ ಕಚ್ಚಾ logits ಇಂದ ನೇರವಾಗಿ ಲೆಕ್ಕಹಾಕಿದ ಒಂದು cross-entropy loss function ಜಾರಿಗೊಳಿಸಿ.\n3. ಕನಿಷ್ಠ 3 ವಿಭಿನ್ನ logit vectors ಗೆ ನಿಮ್ಮ from-scratch cross-entropy loss ಅನ್ನೂ PyTorch ya torch.nn.functional.cross_entropy ವಿರುದ್ಧ ನಿಜವಾಗಿ ಹೋಲಿಸಿ, ಇವುಗಳಲ್ಲಿ ಒಂದು naive implementation overflow ಮಾಡುವ ದೊಡ್ಡ-ಪ್ರಮಾಣದ ಮೌಲ್ಯಗಳೊಂದಿಗೆ." },
  { phaseId, moduleId: m19, lessonId: l19_3, order: 3, difficulty: 'advanced',
    title: 'Genuinely Measuring Temperature Scaling Effects on Softmax Entropy',
    titleKn: 'Softmax Entropy ಮೇಲೆ Temperature Scaling Effects ಅನ್ನೂ ನಿಜವಾಗಿ ಅಳೆಯುವುದೂ',
    problem: "1. Implement a temperature-scaled softmax: softmax(x / T) for a fixed logits vector of your choice (at least 10 classes with varied values).\n2. Genuinely compute and record the output probability distribution's Shannon entropy at 5 different temperature values (e.g. T = 0.1, 0.5, 1.0, 2.0, 5.0).\n3. Plot or tabulate entropy vs. temperature using your real computed numbers, and explain, grounded in what you actually measured, why entropy increases monotonically with temperature for this logits vector -- then find (by binary search or a fine sweep) the approximate temperature at which the distribution's entropy reaches half of the maximum possible entropy (log(num_classes)) for your specific logits, reporting the real T value you found.",
    problemKn: "1. ನಿಮ್ಮ ಆಯ್ಕೆಯ ಒಂದು ಸ್ಥಿರ logits vector ಗೆ ಒಂದು temperature-scaled softmax ಜಾರಿಗೊಳಿಸಿ: softmax(x / T).\n2. 5 ವಿಭಿನ್ನ temperature ಮೌಲ್ಯಗಳಲ್ಲಿ ಔಟ್ಪುಟ್ probability distribution ya Shannon entropy ಅನ್ನೂ ನಿಜವಾಗಿ ಲೆಕ್ಕಹಾಕಿ ಮತ್ತು ದಾಖಲಿಸಿ.\n3. ನಿಮ್ಮ ನಿಜ ಲೆಕ್ಕಹಾಕಿದ ಸಂಖ್ಯೆಗಳನ್ನೂ ಬಳಸಿ entropy vs. temperature ಪ್ಲಾಟ್ ಮಾಡಿ ಅಥವಾ table ಮಾಡಿ, ಮತ್ತು entropy ಗರಿಷ್ಠ ಸಾಧ್ಯ entropy ya ಅರ್ಧಕ್ಕೆ ತಲುಪುವ ಅಂದಾಜು temperature ಕಂಡುಹಿಡಿಯಿರಿ, ನೀವು ಕಂಡುಕೊಂಡ ನಿಜ T ಮೌಲ್ಯ ವರದಿ ಮಾಡಿ." },

  // ── Module 20, Lesson 2: Naive Bayes, MLE, MAP & Log Probabilities ──
  { phaseId, moduleId: m20, lessonId: l20_2, order: 1, difficulty: 'beginner',
    title: 'Genuinely Building a Naive Bayes Spam Classifier',
    titleKn: 'ಒಂದು Naive Bayes Spam Classifier ಅನ್ನೂ ನಿಜವಾಗಿ ನಿರ್ಮಿಸುವುದೂ',
    problem: "1. Construct a genuine small dataset of at least 20 short labeled text messages (spam vs. not-spam), either writing them yourself or using a small public dataset.\n2. Implement a Naive Bayes classifier from scratch: estimate word-given-class probabilities via counting (with Laplace/add-1 smoothing) and compute posterior class probabilities in log-space to avoid underflow.\n3. Genuinely evaluate your classifier on a held-out set of at least 5 messages it wasn't trained on, and report the real accuracy and specific misclassifications, if any -- explain what property of the misclassified message (rare words, unusual phrasing) likely caused the error.",
    problemKn: "1. ಕನಿಷ್ಠ 20 ಚಿಕ್ಕ labeled text messages (spam vs. not-spam) ya ಒಂದು ನಿಜ ಚಿಕ್ಕ dataset ನಿರ್ಮಿಸಿ.\n2. Naive Bayes classifier ಅನ್ನೂ ಮೊದಲಿನಿಂದ ಜಾರಿಗೊಳಿಸಿ: counting ಮೂಲಕ word-given-class probabilities ಅಂದಾಜಿಸಿ (Laplace/add-1 smoothing ಜೊತೆ) ಮತ್ತು underflow ತಪ್ಪಿಸಲು log-space ನಲ್ಲಿ posterior class probabilities ಲೆಕ್ಕಹಾಕಿ.\n3. ಇದು ತರಬೇತಿ ಪಡೆಯದ ಕನಿಷ್ಠ 5 messages ya ಒಂದು held-out set ಮೇಲೆ ನಿಮ್ಮ classifier ಅನ್ನೂ ನಿಜವಾಗಿ ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ, ಮತ್ತು ನಿಜ accuracy ಮತ್ತು ಯಾವುದೇ ನಿರ್ದಿಷ್ಟ ತಪ್ಪು ವರ್ಗೀಕರಣಗಳನ್ನೂ ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m20, lessonId: l20_2, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Comparing MLE vs. MAP Estimation on Sparse Data',
    titleKn: 'ವಿರಳ Data ಮೇಲೆ MLE vs. MAP Estimation ಅನ್ನೂ ನಿಜವಾಗಿ ಹೋಲಿಸುವುದೂ',
    problem: "1. Simulate a coin-flip scenario: generate a genuine sequence of just 5 coin flips from a coin with a true bias of p=0.7 (using a fixed random seed for reproducibility).\n2. Compute the Maximum Likelihood Estimate of p from just these 5 flips (simple frequency).\n3. Compute the Maximum A Posteriori estimate of p using a Beta(2,2) prior, deriving the posterior update analytically (Beta-Bernoulli conjugacy) and computing the MAP as the posterior mode.\n4. Genuinely repeat this experiment (same true p=0.7, same small sample size of 5) across 20 different random seeds, and report the real average absolute error of MLE vs. MAP against the true p=0.7 across those 20 trials -- confirm with actual numbers whether the prior genuinely helps stabilize the estimate on this small-sample regime, rather than assuming it does.",
    problemKn: "1. ಒಂದು coin-flip ಸನ್ನಿವೇಶ simulate ಮಾಡಿ: p=0.7 ನಿಜ bias ಇರುವ ಒಂದು coin ಇಂದ ಕೇವಲ 5 coin flips ya ಒಂದು ನಿಜ ಅನುಕ್ರಮ ಉತ್ಪಾದಿಸಿ.\n2. ಈ ಕೇವಲ 5 flips ಇಂದ p ya Maximum Likelihood Estimate ಲೆಕ್ಕಹಾಕಿ.\n3. Beta(2,2) prior ಬಳಸಿ p ya Maximum A Posteriori estimate ಲೆಕ್ಕಹಾಕಿ, posterior update ಅನ್ನೂ analytically ಪಡೆದು MAP ಅನ್ನೂ posterior mode ಆಗಿ ಲೆಕ್ಕಹಾಕಿ.\n4. ಈ ಪ್ರಯೋಗವನ್ನೂ 20 ವಿಭಿನ್ನ random seeds ಗಳಾದ್ಯಂತ ನಿಜವಾಗಿ ಪುನರಾವರ್ತಿಸಿ, ಮತ್ತು ಆ 20 ಪ್ರಯತ್ನಗಳಾದ್ಯಂತ ನಿಜ p=0.7 ವಿರುದ್ಧ MLE vs. MAP ya ನಿಜ ಸರಾಸರಿ absolute error ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m20, lessonId: l20_2, order: 3, difficulty: 'advanced',
    title: 'Genuinely Testing the Naive Independence Assumption',
    titleKn: 'Naive Independence Assumption ಅನ್ನೂ ನಿಜವಾಗಿ ಪರೀಕ್ಷಿಸುವುದೂ',
    problem: "1. Using your Naive Bayes classifier from the earlier exercise, deliberately construct a small test set where the 'naive' conditional-independence assumption between features is genuinely violated (e.g. two words that always co-occur together, so their joint evidence is being double-counted by the independence assumption).\n2. Measure your classifier's real accuracy and confidence (posterior probability) on this deliberately-correlated test set versus a test set where features are genuinely closer to independent.\n3. Report the real accuracy/confidence numbers for both test sets, and explain concretely (using the specific correlated-word example you constructed) why Naive Bayes systematically overstates its confidence when features are correlated -- trace through the actual log-probability arithmetic to show where the double-counting happens.",
    problemKn: "1. ಹಿಂದಿನ ವ್ಯಾಯಾಮದ ನಿಮ್ಮ Naive Bayes classifier ಬಳಸಿ, features ನಡುವಿನ 'naive' conditional-independence ಊಹೆ ನಿಜವಾಗಿ ಉಲ್ಲಂಘಿಸಲ್ಪಟ್ಟ ಒಂದು ಚಿಕ್ಕ test set ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ನಿರ್ಮಿಸಿ.\n2. ಈ ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ-ಸಂಬಂಧಿತ test set ಮತ್ತು features ನಿಜವಾಗಿ ಸ್ವತಂತ್ರಕ್ಕೆ ಹತ್ತಿರವಿರುವ ಒಂದು test set ಮೇಲೆ ನಿಮ್ಮ classifier ya ನಿಜ accuracy ಮತ್ತು confidence ಅಳೆಯಿರಿ.\n3. ಎರಡೂ test sets ಗೆ ನಿಜ accuracy/confidence ಸಂಖ್ಯೆಗಳನ್ನೂ ವರದಿ ಮಾಡಿ, ಮತ್ತು features ಸಂಬಂಧಿತವಾಗಿದ್ದಾಗ Naive Bayes ಏಕೆ ವ್ಯವಸ್ಥಿತವಾಗಿ ತನ್ನ confidence ಅನ್ನೂ ಅತಿಯಾಗಿ ಹೇಳುತ್ತದೆ ಎಂದು ನಿರ್ದಿಷ್ಟವಾಗಿ ವಿವರಿಸಿ." },

  // ── Module 20, Lesson 3: Conjugate Priors & A/B Testing ──
  { phaseId, moduleId: m20, lessonId: l20_3, order: 1, difficulty: 'beginner',
    title: 'Genuinely Simulating a Beta-Binomial A/B Test',
    titleKn: 'ಒಂದು Beta-Binomial A/B Test ಅನ್ನೂ ನಿಜವಾಗಿ ಸಿಮ್ಯುಲೇಟ್ ಮಾಡುವುದೂ',
    problem: "1. Simulate genuine conversion data for two variants: Variant A with true conversion rate 0.10 and Variant B with true conversion rate 0.12, each shown to 500 simulated users (using a fixed random seed).\n2. Using a Beta(1,1) uninformative prior for each variant, compute the posterior Beta distribution for each variant's conversion rate given your simulated data.\n3. Genuinely sample 10,000 draws from each posterior and compute the empirical probability that Variant B's true rate exceeds Variant A's (P(B > A)), reporting the real number you calculated -- then re-run the whole simulation with a much smaller sample size (50 users per variant instead of 500) and report how much your P(B > A) estimate's uncertainty (width of its distribution) changes, with real numbers from both runs.",
    problemKn: "1. ಎರಡು variants ಗಳಿಗೆ ನಿಜ conversion data simulate ಮಾಡಿ: Variant A 0.10 ನಿಜ conversion rate ಜೊತೆ ಮತ್ತು Variant B 0.12 ಜೊತೆ, ಪ್ರತಿಯೊಂದನ್ನೂ 500 simulated users ಗೆ ತೋರಿಸಲಾಗಿದೆ.\n2. ಪ್ರತಿ variant ಗೆ ಒಂದು Beta(1,1) uninformative prior ಬಳಸಿ, ನಿಮ್ಮ simulated data ಆಧರಿಸಿ ಪ್ರತಿ variant ya conversion rate ಗೆ posterior Beta distribution ಲೆಕ್ಕಹಾಕಿ.\n3. ಪ್ರತಿ posterior ಇಂದ 10,000 draws ಸ್ಯಾಂಪಲ್ ಮಾಡಿ ಮತ್ತು Variant B ya ನಿಜ rate Variant A ya ಮೀರುತ್ತದೆ ಎಂಬ empirical probability ಲೆಕ್ಕಹಾಕಿ, ನೀವು ಲೆಕ್ಕಹಾಕಿದ ನಿಜ ಸಂಖ್ಯೆ ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m20, lessonId: l20_3, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Deriving and Verifying Beta-Bernoulli Conjugacy',
    titleKn: 'Beta-Bernoulli Conjugacy ಅನ್ನೂ ನಿಜವಾಗಿ ಪಡೆಯುವುದೂ ಮತ್ತು ಪರಿಶೀಲಿಸುವುದೂ',
    problem: "1. Starting from a Beta(alpha, beta) prior and a sequence of Bernoulli observations, derive the closed-form posterior update rule by hand (showing the proportionality argument that leads to Beta(alpha + successes, beta + failures)).\n2. Genuinely implement a numerical check: starting with Beta(2, 3), observe 7 successes and 3 failures, compute the posterior parameters using your derived formula, and separately verify this is correct by numerically computing the (unnormalized) posterior density at several points using Bayes' rule directly (prior density times likelihood) and confirming it's proportional to your closed-form Beta posterior's density at those same points.\n3. Report the real proportionality constant you find between the two computations, and explain why conjugate priors let you skip the (often intractable) normalization integral in Bayes' rule.",
    problemKn: "1. ಒಂದು Beta(alpha, beta) prior ಮತ್ತು Bernoulli observations ya ಒಂದು ಅನುಕ್ರಮ ಇಂದ ಪ್ರಾರಂಭಿಸಿ, closed-form posterior update ನಿಯಮವನ್ನೂ ಕೈಯಾರೆ ಪಡೆಯಿರಿ.\n2. Beta(2, 3) ಇಂದ ಪ್ರಾರಂಭಿಸಿ, 7 successes ಮತ್ತು 3 failures ಗಮನಿಸಿ, ನಿಮ್ಮ ಪಡೆದ formula ಬಳಸಿ posterior parameters ಲೆಕ್ಕಹಾಕಿ, ಮತ್ತು Bayes' rule ನೇರವಾಗಿ ಬಳಸಿ ಸಂಖ್ಯಾತ್ಮಕವಾಗಿ ಪರಿಶೀಲಿಸಿ.\n3. ಎರಡು ಲೆಕ್ಕಾಚಾರಗಳ ನಡುವೆ ನೀವು ಕಂಡುಕೊಂಡ ನಿಜ proportionality constant ವರದಿ ಮಾಡಿ, ಮತ್ತು conjugate priors ಏಕೆ Bayes' rule ನಲ್ಲಿ normalization integral ಬಿಟ್ಟುಬಿಡಲು ಅನುಮತಿಸುತ್ತವೆ ಎಂದು ವಿವರಿಸಿ." },
  { phaseId, moduleId: m20, lessonId: l20_3, order: 3, difficulty: 'advanced',
    title: 'Genuinely Measuring Sequential A/B Testing Peeking Risk',
    titleKn: 'Sequential A/B Testing Peeking Risk ಅನ್ನೂ ನಿಜವಾಗಿ ಅಳೆಯುವುದೂ',
    problem: "1. Simulate a null-effect A/B test: both variants have the IDENTICAL true conversion rate of 0.10, run for 2000 simulated users each.\n2. Implement 'continuous peeking': after every 50 new users added, recompute the Bayesian posterior P(B > A) and check whether it crosses a naive decision threshold (e.g. > 0.95) at any point during the whole run, even if it later returns to near 0.5.\n3. Genuinely repeat this entire null-effect simulation 200 times (200 independent 2000-user experiments where there is truly no difference), and report the real fraction of your 200 simulated experiments where continuous peeking falsely triggered a 'B is better' conclusion at some point -- compare this real false-positive rate to what you'd expect from a single, pre-registered check at the end of the experiment, and explain concretely why repeated peeking inflates false positives even though each individual snapshot's Bayesian math is correct.",
    problemKn: "1. ಒಂದು null-effect A/B test simulate ಮಾಡಿ: ಎರಡೂ variants 0.10 ya ಒಂದೇ ನಿಜ conversion rate ಹೊಂದಿವೆ, ಪ್ರತಿಯೊಂದಕ್ಕೂ 2000 simulated users ಗೆ ಚಲಾಯಿಸಲಾಗಿದೆ.\n2. 'continuous peeking' ಜಾರಿಗೊಳಿಸಿ: ಪ್ರತಿ 50 ಹೊಸ users ಸೇರಿಸಿದ ನಂತರ, Bayesian posterior P(B > A) ಮರುಲೆಕ್ಕಹಾಕಿ ಮತ್ತು ಇದು ಇಡೀ ಚಲಾವಣೆಯ ಸಮಯದಲ್ಲಿ ಯಾವುದೇ ಬಿಂದುವಿನಲ್ಲಿ ಒಂದು naive decision threshold ದಾಟುತ್ತದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.\n3. ಈ ಸಂಪೂರ್ಣ null-effect simulation ಅನ್ನೂ 200 ಬಾರಿ ನಿಜವಾಗಿ ಪುನರಾವರ್ತಿಸಿ, ಮತ್ತು continuous peeking ಒಂದು ಬಿಂದುವಿನಲ್ಲಿ ತಪ್ಪಾಗಿ 'B ಉತ್ತಮ' ಎಂಬ ತೀರ್ಮಾನ ಪ್ರಚೋದಿಸಿದ ನಿಮ್ಮ 200 simulated ಪ್ರಯೋಗಗಳ ನಿಜ ಭಾಗ ವರದಿ ಮಾಡಿ." },

  // ── Module 21, Lesson 1: Gradient Descent & the Rosenbrock Valley ──
  { phaseId, moduleId: m21, lessonId: l21_1, order: 1, difficulty: 'beginner',
    title: 'Genuinely Implementing Gradient Descent on the Rosenbrock Function',
    titleKn: 'Rosenbrock Function ಮೇಲೆ Gradient Descent ಅನ್ನೂ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ',
    problem: "1. Implement the Rosenbrock function f(x,y) = (1-x)^2 + 100*(y-x^2)^2 and its analytical gradient (derive it by hand and implement both formulas).\n2. Implement plain gradient descent starting from (x,y) = (-1, 1), and run it for 1000 iterations with a genuinely chosen fixed learning rate.\n3. Track and plot the loss value at every iteration. Report the real final (x,y) position and how close it is to the true minimum at (1,1). Try at least 2 different learning rates and report, with real numbers, which one converges faster and which one diverges or oscillates -- do not assume a 'reasonable' learning rate will work without testing it.",
    problemKn: "1. Rosenbrock function f(x,y) = (1-x)^2 + 100*(y-x^2)^2 ಮತ್ತು ಅದರ analytical gradient ಜಾರಿಗೊಳಿಸಿ.\n2. (x,y) = (-1, 1) ಇಂದ ಪ್ರಾರಂಭಿಸಿ plain gradient descent ಜಾರಿಗೊಳಿಸಿ, ಮತ್ತು ಒಂದು ನಿಜವಾಗಿ ಆಯ್ಕೆ ಮಾಡಿದ ಸ್ಥಿರ learning rate ಜೊತೆ 1000 iterations ಚಲಾಯಿಸಿ.\n3. ಪ್ರತಿ iteration ನಲ್ಲಿ loss ಮೌಲ್ಯ ಟ್ರ್ಯಾಕ್ ಮಾಡಿ ಮತ್ತು ಪ್ಲಾಟ್ ಮಾಡಿ. ನಿಜ ಅಂತಿಮ (x,y) ಸ್ಥಾನ ಮತ್ತು ಇದು (1,1) ನಲ್ಲಿ ನಿಜ minimum ಗೆ ಎಷ್ಟು ಹತ್ತಿರವಾಗಿದೆ ಎಂದು ವರದಿ ಮಾಡಿ. ಕನಿಷ್ಠ 2 ವಿಭಿನ್ನ learning rates ಪ್ರಯತ್ನಿಸಿ ಮತ್ತು ಯಾವುದೂ ವೇಗವಾಗಿ ಒಮ್ಮುಖವಾಗುತ್ತದೆ ಎಂದು ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m21, lessonId: l21_1, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Visualizing Why the Rosenbrock Valley Is Hard for Gradient Descent',
    titleKn: 'Rosenbrock Valley ಗ್ರೇಡಿಯಂಟ್ ಡಿಸೆಂಟ್ ಗೆ ಏಕೆ ಕಷ್ಟ ಎಂದು ನಿಜವಾಗಿ ದೃಶ್ಯೀಕರಿಸುವುದೂ',
    problem: "1. Compute the Rosenbrock function's value on a genuine 2D grid (e.g. x, y both ranging from -2 to 2 with a fine step), and plot a contour or heatmap to visualize the actual curved, narrow valley shape.\n2. Run your gradient descent implementation from the previous exercise and overlay its actual trajectory (the sequence of (x,y) points it visited) on top of your contour plot.\n3. Based on what you genuinely observe in the trajectory plot, describe specifically where and why the optimizer zig-zags or slows down (identify the actual iteration range where progress visibly stalls), connecting this to the real difference in curvature you can measure along versus across the valley (e.g. by computing the Hessian's eigenvalues at a point inside the valley and reporting their ratio).",
    problemKn: "1. ಒಂದು ನಿಜ 2D grid ಮೇಲೆ Rosenbrock function ya ಮೌಲ್ಯ ಲೆಕ್ಕಹಾಕಿ, ಮತ್ತು ನಿಜ ಬಾಗಿದ, ಕಿರಿದಾದ valley ಆಕಾರ ದೃಶ್ಯೀಕರಿಸಲು ಒಂದು contour ಅಥವಾ heatmap ಪ್ಲಾಟ್ ಮಾಡಿ.\n2. ಹಿಂದಿನ ವ್ಯಾಯಾಮದ ನಿಮ್ಮ gradient descent implementation ಚಲಾಯಿಸಿ ಮತ್ತು ಅದರ ನಿಜ trajectory ಅನ್ನೂ ನಿಮ್ಮ contour plot ಮೇಲೆ overlay ಮಾಡಿ.\n3. trajectory plot ನಲ್ಲಿ ನೀವು ನಿಜವಾಗಿ ಗಮನಿಸುವ ಆಧಾರದ ಮೇಲೆ, optimizer ಎಲ್ಲಿ ಮತ್ತು ಏಕೆ zig-zag ಮಾಡುತ್ತದೆ ಅಥವಾ ನಿಧಾನವಾಗುತ್ತದೆ ಎಂದು ನಿರ್ದಿಷ್ಟವಾಗಿ ವಿವರಿಸಿ, ಇದನ್ನೂ valley ಉದ್ದಕ್ಕೂ vs ಅಡ್ಡಲಾಗಿ curvature ವ್ಯತ್ಯಾಸಕ್ಕೆ ಸಂಪರ್ಕಿಸಿ." },
  { phaseId, moduleId: m21, lessonId: l21_1, order: 3, difficulty: 'advanced',
    title: 'Genuinely Benchmarking Fixed vs. Adaptive Step Sizes on Rosenbrock',
    titleKn: 'Rosenbrock ಮೇಲೆ Fixed vs. Adaptive Step Sizes ಅನ್ನೂ ನಿಜವಾಗಿ Benchmark ಮಾಡುವುದೂ',
    problem: "1. Implement a simple backtracking line search (Armijo condition) on top of your gradient descent implementation, so the step size is genuinely chosen adaptively at each iteration rather than fixed in advance.\n2. Genuinely run both your fixed-step-size gradient descent (using the best fixed rate you found earlier) and your new line-search version on the Rosenbrock function from the same starting point, tracking the real number of iterations each needs to reach a loss below a threshold you choose (e.g. 1e-6).\n3. Report the real iteration counts and wall-clock times for both methods (accounting for the extra function evaluations the line search itself costs per iteration), and state concretely, based on your measured numbers, whether the adaptive method's extra per-iteration cost was worth it for this specific problem -- don't assume adaptive methods always win without checking the real overhead.",
    problemKn: "1. ನಿಮ್ಮ gradient descent implementation ಮೇಲೆ ಒಂದು ಸರಳ backtracking line search (Armijo condition) ಜಾರಿಗೊಳಿಸಿ, ಇದರಿಂದ step size ಪ್ರತಿ iteration ನಲ್ಲಿ ನಿಜವಾಗಿ ಹೊಂದಾಣಿಕೆಯಾಗುತ್ತದೆ.\n2. ನಿಮ್ಮ fixed-step-size gradient descent ಮತ್ತು ನಿಮ್ಮ ಹೊಸ line-search ಆವೃತ್ತಿ ಎರಡನ್ನೂ Rosenbrock function ಮೇಲೆ ಅದೇ ಪ್ರಾರಂಭ ಬಿಂದುವಿನಿಂದ ನಿಜವಾಗಿ ಚಲಾಯಿಸಿ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ಒಂದು threshold ಗಿಂತ ಕಡಿಮೆ loss ತಲುಪಲು ಬೇಕಾದ ನಿಜ iterations ಸಂಖ್ಯೆ ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.\n3. ಎರಡೂ ವಿಧಾನಗಳಿಗೆ ನಿಜ iteration counts ಮತ್ತು wall-clock times ವರದಿ ಮಾಡಿ, ಮತ್ತು ನಿಮ್ಮ ಅಳೆದ ಸಂಖ್ಯೆಗಳ ಆಧಾರದ ಮೇಲೆ adaptive ವಿಧಾನ ya ಹೆಚ್ಚುವರಿ ವೆಚ್ಚ ಈ ನಿರ್ದಿಷ್ಟ ಸಮಸ್ಯೆಗೆ ಯೋಗ್ಯವಾಗಿತ್ತೇ ಎಂದು ನಿರ್ದಿಷ್ಟವಾಗಿ ಹೇಳಿ." },

  // ── Module 21, Lesson 2: Momentum and Adam ──
  { phaseId, moduleId: m21, lessonId: l21_2, order: 1, difficulty: 'beginner',
    title: 'Genuinely Implementing SGD With Momentum From Scratch',
    titleKn: 'Momentum ಜೊತೆ SGD ಅನ್ನೂ ಮೊದಲಿನಿಂದ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ',
    problem: "1. Implement plain SGD and SGD-with-momentum (v = beta*v + gradient; params -= lr*v) from scratch as two separate optimizer functions.\n2. Run both on the Rosenbrock function from Module 21 Part 1's starting point, using the same learning rate for both and a genuinely chosen momentum beta (e.g. 0.9).\n3. Track and plot both methods' loss curves over the same number of iterations, and report the real iteration count each needs to reach a loss threshold you choose. Confirm with actual numbers whether momentum genuinely accelerates convergence on this specific problem, and if you observe momentum overshooting or oscillating at any point, report exactly which iterations show that behavior.",
    problemKn: "1. plain SGD ಮತ್ತು SGD-with-momentum ಅನ್ನೂ ಮೊದಲಿನಿಂದ ಎರಡು ಪ್ರತ್ಯೇಕ optimizer functions ಆಗಿ ಜಾರಿಗೊಳಿಸಿ.\n2. Module 21 Part 1 ya ಪ್ರಾರಂಭ ಬಿಂದುವಿನಿಂದ Rosenbrock function ಮೇಲೆ ಎರಡನ್ನೂ ಚಲಾಯಿಸಿ, ಎರಡಕ್ಕೂ ಅದೇ learning rate ಬಳಸಿ.\n3. ಅದೇ iterations ಸಂಖ್ಯೆಯಾದ್ಯಂತ ಎರಡೂ ವಿಧಾನಗಳ loss curves ಟ್ರ್ಯಾಕ್ ಮಾಡಿ ಮತ್ತು ಪ್ಲಾಟ್ ಮಾಡಿ, ಮತ್ತು ಪ್ರತಿಯೊಂದಕ್ಕೂ ಒಂದು loss threshold ತಲುಪಲು ಬೇಕಾದ ನಿಜ iteration count ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m21, lessonId: l21_2, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Implementing Adam From Scratch and Matching PyTorch',
    titleKn: 'Adam ಅನ್ನೂ ಮೊದಲಿನಿಂದ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ ಮತ್ತು PyTorch ಜೊತೆ ಹೊಂದಿಸುವುದೂ',
    problem: "1. Implement the full Adam optimizer from scratch: first and second moment estimates (m, v), bias correction, and the parameter update rule, using the standard hyperparameters (beta1=0.9, beta2=0.999, epsilon=1e-8).\n2. Run your from-scratch Adam on a simple test function (e.g. a 2D quadratic bowl) for 20 steps from a fixed starting point, recording the parameter values at every step.\n3. Genuinely reproduce the identical setup in PyTorch using torch.optim.Adam with the same hyperparameters, learning rate, and starting point, run it for the same 20 steps, and compare your from-scratch parameter trajectory to PyTorch's step by step. Report the real max absolute difference across all 20 steps -- if there's a meaningful discrepancy, debug whether it's a bias-correction formula error or a hyperparameter mismatch.",
    problemKn: "1. ಪೂರ್ಣ Adam optimizer ಅನ್ನೂ ಮೊದಲಿನಿಂದ ಜಾರಿಗೊಳಿಸಿ: first ಮತ್ತು second moment estimates (m, v), bias correction, ಮತ್ತು parameter update ನಿಯಮ, standard hyperparameters ಬಳಸಿ.\n2. ಒಂದು ಸ್ಥಿರ ಪ್ರಾರಂಭ ಬಿಂದುವಿನಿಂದ ಒಂದು ಸರಳ test function ಮೇಲೆ 20 steps ಗೆ ನಿಮ್ಮ from-scratch Adam ಚಲಾಯಿಸಿ, ಪ್ರತಿ step ನಲ್ಲಿ parameter ಮೌಲ್ಯಗಳು ದಾಖಲಿಸಿ.\n3. PyTorch ya torch.optim.Adam ಬಳಸಿ ಅದೇ setup ಅನ್ನೂ ನಿಜವಾಗಿ ಮರುಉತ್ಪಾದಿಸಿ, ಅದೇ 20 steps ಚಲಾಯಿಸಿ, ಮತ್ತು ನಿಮ್ಮ from-scratch parameter trajectory ಅನ್ನೂ PyTorch ya ಜೊತೆ step ಮೂಲಕ step ಹೋಲಿಸಿ. ಎಲ್ಲಾ 20 steps ಗಳಾದ್ಯಂತ ನಿಜ ಗರಿಷ್ಠ absolute difference ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m21, lessonId: l21_2, order: 3, difficulty: 'advanced',
    title: "Genuinely Measuring Momentum's and Adam's Behavior on a Saddle Point",
    titleKn: 'ಒಂದು Saddle Point ಮೇಲೆ Momentum ಮತ್ತು Adam ya ವರ್ತನೆಯನ್ನೂ ನಿಜವಾಗಿ ಅಳೆಯುವುದೂ',
    problem: "1. Construct a genuine 2D function with a saddle point at the origin (e.g. f(x,y) = x^2 - y^2), and start plain gradient descent exactly at (0, 1e-8) (deliberately very close to the saddle's unstable direction with a tiny perturbation).\n2. Genuinely run plain SGD, SGD-with-momentum, and Adam from this same near-saddle starting point for a fixed number of iterations, tracking the (x,y) trajectory for each.\n3. Report which optimizer(s), based on your real measured trajectories, escape the vicinity of the saddle point fastest (moving away in the unstable y-direction), and which stay trapped near the saddle longest. Explain the escape-speed difference concretely by relating it to how each optimizer's update rule amplifies or dampens a small initial gradient in the unstable direction -- support your explanation with the actual numeric trajectory data, not just the general theory.",
    problemKn: "1. ಮೂಲದಲ್ಲಿ ಒಂದು saddle point ಇರುವ ಒಂದು ನಿಜ 2D function ನಿರ್ಮಿಸಿ (ಉದಾ f(x,y) = x^2 - y^2), ಮತ್ತು (0, 1e-8) ನಲ್ಲಿ ನಿಖರವಾಗಿ plain gradient descent ಪ್ರಾರಂಭಿಸಿ.\n2. ಈ ಅದೇ ಸಮೀಪ-saddle ಪ್ರಾರಂಭ ಬಿಂದುವಿನಿಂದ plain SGD, SGD-with-momentum, ಮತ್ತು Adam ಅನ್ನೂ ಒಂದು ಸ್ಥಿರ iterations ಸಂಖ್ಯೆಗೆ ನಿಜವಾಗಿ ಚಲಾಯಿಸಿ, ಪ್ರತಿಯೊಂದಕ್ಕೂ (x,y) trajectory ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.\n3. ನಿಮ್ಮ ನಿಜ ಅಳೆದ trajectories ಆಧರಿಸಿ, ಯಾವ optimizer(s) saddle point ya ಸಮೀಪವನ್ನೂ ಅತ್ಯಂತ ವೇಗವಾಗಿ ತಪ್ಪಿಸಿಕೊಳ್ಳುತ್ತವೆ ಮತ್ತು ಯಾವುದೂ ಅತ್ಯಂತ ಹೆಚ್ಚು ಕಾಲ ಸಿಕ್ಕಿಬೀಳುತ್ತವೆ ಎಂದು ವರದಿ ಮಾಡಿ." },

  // ── Module 21, Lesson 3: Learning-Rate Schedules, Loss Landscapes & Production Optimizers ──
  { phaseId, moduleId: m21, lessonId: l21_3, order: 1, difficulty: 'beginner',
    title: 'Genuinely Implementing and Comparing Three Learning-Rate Schedules',
    titleKn: 'ಮೂರು Learning-Rate Schedules ಅನ್ನೂ ನಿಜವಾಗಿ ಜಾರಿಗೊಳಿಸುವುದೂ ಮತ್ತು ಹೋಲಿಸುವುದೂ',
    problem: "1. Implement three learning-rate schedule functions from scratch: step decay (halve the LR every N steps), cosine annealing, and linear warmup followed by cosine decay.\n2. For a fixed total of 200 steps, genuinely compute and plot the actual learning-rate value produced by each schedule at every step.\n3. Apply all three schedules to your Adam optimizer from the previous exercise on the Rosenbrock function, and report the real final loss each schedule achieves after 200 steps, plus which schedule converged fastest in the first 50 steps versus which achieved the lowest final loss overall -- these need not be the same schedule, so report both findings with real numbers.",
    problemKn: "1. ಮೂರು learning-rate schedule functions ಅನ್ನೂ ಮೊದಲಿನಿಂದ ಜಾರಿಗೊಳಿಸಿ: step decay, cosine annealing, ಮತ್ತು linear warmup ನಂತರ cosine decay.\n2. ಒಟ್ಟು 200 steps ಗೆ, ಪ್ರತಿ schedule ಪ್ರತಿ step ನಲ್ಲಿ ಉತ್ಪಾದಿಸುವ ನಿಜ learning-rate ಮೌಲ್ಯ ನಿಜವಾಗಿ ಲೆಕ್ಕಹಾಕಿ ಮತ್ತು ಪ್ಲಾಟ್ ಮಾಡಿ.\n3. ಮೂರೂ schedules ಅನ್ನೂ Rosenbrock function ಮೇಲೆ ನಿಮ್ಮ Adam optimizer ಗೆ ಅನ್ವಯಿಸಿ, ಮತ್ತು 200 steps ನಂತರ ಪ್ರತಿ schedule ಸಾಧಿಸುವ ನಿಜ ಅಂತಿಮ loss ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m21, lessonId: l21_3, order: 2, difficulty: 'intermediate',
    title: 'Genuinely Visualizing a 2D Loss Landscape Slice for a Small Neural Network',
    titleKn: 'ಒಂದು ಚಿಕ್ಕ Neural Network ಗಾಗಿ ಒಂದು 2D Loss Landscape Slice ಅನ್ನೂ ನಿಜವಾಗಿ ದೃಶ್ಯೀಕರಿಸುವುದೂ',
    problem: "1. Train a small neural network (e.g. a 2-layer MLP on a toy classification dataset like make_moons) to convergence, and save its final weight vector.\n2. Generate two genuine random direction vectors in weight-space (with the same shape as the full parameter vector), and compute the loss on a grid of points of the form final_weights + alpha*dir1 + beta*dir2 for a range of alpha, beta values around 0.\n3. Plot this as a contour or 3D surface, and report, based on what you genuinely observe in your specific trained model's landscape slice, whether the minimum you found looks like a sharp, narrow basin or a wide, flat one -- and discuss concretely what this observed sharpness/flatness might imply about this specific model's generalization, connecting it to the actual loss values you measured just outside the minimum in your grid.",
    problemKn: "1. ಒಂದು ಚಿಕ್ಕ neural network ಅನ್ನೂ (ಉದಾ make_moons ನಂತಹ ಒಂದು toy dataset ಮೇಲೆ 2-layer MLP) ಒಮ್ಮುಖವಾಗುವವರೆಗೆ train ಮಾಡಿ, ಮತ್ತು ಅದರ ಅಂತಿಮ weight vector ಉಳಿಸಿ.\n2. weight-space ನಲ್ಲಿ ಎರಡು ನಿಜ ಯಾದೃಚ್ಛಿಕ direction vectors ಉತ್ಪಾದಿಸಿ, ಮತ್ತು alpha, beta ಮೌಲ್ಯಗಳ ಒಂದು ಶ್ರೇಣಿಗೆ final_weights + alpha*dir1 + beta*dir2 ರೂಪದ ಬಿಂದುಗಳ ಒಂದು grid ಮೇಲೆ loss ಲೆಕ್ಕಹಾಕಿ.\n3. ಇದನ್ನೂ ಒಂದು contour ಅಥವಾ 3D surface ಆಗಿ ಪ್ಲಾಟ್ ಮಾಡಿ, ಮತ್ತು ನೀವು ನಿಜವಾಗಿ ಗಮನಿಸುವ ಆಧಾರದ ಮೇಲೆ, ನೀವು ಕಂಡುಕೊಂಡ minimum ಒಂದು ತೀಕ್ಷ್ಣ, ಕಿರಿದಾದ basin ನಂತೆ ಅಥವಾ ಒಂದು ವಿಶಾಲ, ಸಮತಟ್ಟಾದ ಒಂದನ್ನೂ ಕಾಣುತ್ತದೆಯೇ ಎಂದು ವರದಿ ಮಾಡಿ." },
  { phaseId, moduleId: m21, lessonId: l21_3, order: 3, difficulty: 'advanced',
    title: 'Genuinely Benchmarking AdamW vs. Adam With Weight Decay on Overfitting',
    titleKn: 'Overfitting ಮೇಲೆ AdamW vs. Weight Decay ಜೊತೆ Adam ಅನ್ನೂ ನಿಜವಾಗಿ Benchmark ಮಾಡುವುದೂ',
    problem: "1. Set up a small neural network prone to overfitting on a small dataset (e.g. an over-parameterized MLP on a tiny subset of a toy dataset with added label noise).\n2. Train two genuinely separate copies of this network for the same number of epochs: one using PyTorch's Adam optimizer with L2 regularization added directly to the loss, and one using torch.optim.AdamW with an equivalent weight_decay value.\n3. Genuinely track and report both training and validation loss curves for both optimizers across training, and report the real final train/validation loss gap for each -- explain, based on your specific measured curves (not the general AdamW paper claim), whether AdamW's decoupled weight decay produced a measurably different regularization effect than naive L2-in-Adam on this specific small-scale experiment, or whether the difference was negligible at this scale.",
    problemKn: "1. ಒಂದು ಚಿಕ್ಕ dataset ಮೇಲೆ overfitting ಗೆ ಒಳಗಾಗುವ ಒಂದು ಚಿಕ್ಕ neural network ಸ್ಥಾಪಿಸಿ.\n2. ಈ network ya ಎರಡು ನಿಜ ಪ್ರತ್ಯೇಕ ಪ್ರತಿಗಳನ್ನೂ ಅದೇ epochs ಸಂಖ್ಯೆಗೆ ತರಬೇತಿ ನೀಡಿ: ಒಂದು loss ಗೆ ನೇರವಾಗಿ ಸೇರಿಸಿದ L2 regularization ಜೊತೆ PyTorch ya Adam optimizer ಬಳಸಿ, ಮತ್ತು ಒಂದು ಸಮಾನ weight_decay ಮೌಲ್ಯ ಜೊತೆ torch.optim.AdamW ಬಳಸಿ.\n3. ಎರಡೂ optimizers ಗಾಗಿ training ಮತ್ತು validation loss curves ಎರಡನ್ನೂ ನಿಜವಾಗಿ ಟ್ರ್ಯಾಕ್ ಮಾಡಿ ಮತ್ತು ವರದಿ ಮಾಡಿ, ಮತ್ತು ಪ್ರತಿಯೊಂದಕ್ಕೂ ನಿಜ ಅಂತಿಮ train/validation loss ಅಂತರ ವರದಿ ಮಾಡಿ." },
];
